use vstd::prelude::*;

verus! {

/// A specification that a sequence `a` has at most one distinct element:
/// i.e. every element equals the first, or the sequence is empty.
spec fn only_one(a: Seq<i32>) -> bool {
    if Seq::len(a) == 0 {
        true
    } else {
        forall |i: nat| i < Seq::len(a) ==> a[i] == a[0]
    }
}

fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool
    ensures
        // The result agrees with the spec on the vector's sequence
        result == only_one(to_seq(arr))
{
    let n: usize = arr.len();
    // Empty or singleton arrays vacuously have only one distinct element
    if n <= 1 {
        return true;
    }
    // Convert to a specification sequence once
    let a: Seq<i32> = to_seq(arr);
    // Remember the first element
    let first: i32 = a[0];
    // We'll scan from index 1 up to n
    let mut i: usize = 1;
    // Loop invariant: we have checked all indices < i, and they match `first`
    while i < n
        invariant
            1 <= i <= n,
            forall |j: nat| j < i ==> a[j] == first
        decreases (n - i)
    {
        // If we find a mismatch, we can immediately conclude "false"
        if arr[i] != first {
            return false;
        }
        // Otherwise extend the checked prefix
        i = i + 1;
    }
    // If we never saw a mismatch, return true
    true
}

} // verus!

fn main() {
    // Simple smoke tests (not verified by Verus, just to satisfy Rust)
    let v1: Vec<i32> = vec![];
    let v2: Vec<i32> = vec![42];
    let v3: Vec<i32> = vec![7, 7, 7, 7];
    let v4: Vec<i32> = vec![1, 2, 1];
    assert!(has_only_one_distinct_element(&v1));
    assert!(has_only_one_distinct_element(&v2));
    assert!(has_only_one_distinct_element(&v3));
    assert!(!has_only_one_distinct_element(&v4));
}